public static void lookupOrderClasses(FormControl _callingControl)
{
    SysTableLookup                  sysTableLookup  = SysTableLookup::newParameters(tablenum(TFMDocumentTmpHandlerLookup), _callingControl);
    classId                         classId;
    SysDictClass                    DC;
    TFMPostMethodAttribute          attr;
    TFMDocumentTypeAttribute        docTypeAttr;
    Array                           array, arr2;
    int                             i, j, k;
    DictMethod                      DM;
    List                            attributeClasses = new SysDictClass(classnum(MobOrder)).extendedBy();
    ListEnumerator                  lEnum = attributeClasses.getEnumerator();
    TFMDocumentTmpHandlerLookup     tmpLookup;
    Set                             addedClasses = new Set(Types::String);
    str                             clsPlusMethod;

    sysTableLookup.addLookupfield(fieldNum(TFMDocumentTmpHandlerLookup,className),true);
    sysTableLookup.addLookupfield(fieldNum(TFMDocumentTmpHandlerLookup,Description));

    tmpLookup.setTmp();

    while (lEnum.moveNext())
    {
        classId = lEnum.current();

        tmpLookup.Description = TFMDisplayLineOverride::classId2Attribute(classId);
        if (!tmpLookup.Description)
        {
            continue;
        }
        tmpLookup.ClassName = classId2Name(classId);
        tmpLookup.insert();
    }

    classId = classnum(TFMDocumentHandler);
    lEnum = new SysDictClass(classId).extendedBy().getEnumerator();

    while (lEnum.moveNext())
    {
        classId = lEnum.current();
        DC = new SysDictClass(classId);
        for (i = 1; i <= DC.objectMethodCnt(); i++)
        {
            DM = DC.objectMethodObject(i);
            array = DM.getAttributes(classStr(TFMPostMethodAttribute));
            if (array != null)
            {
                for (j = 1; j <= array.lastIndex(); j++)
                {
                    clsPlusMethod = DC.name() + '.' + DM.name();
                    if (addedClasses.in(DC.name() + '.' + DM.name()))
                    {
                        continue;
                    }
                    attr = array.value(j);
                    arr2 = DM.getAttributes(classStr(TFMDocumentTypeAttribute));
                    for (k = 1; k <= arr2.lastIndex(); k++)
                    {
                        docTypeAttr = arr2.value(k);

                        if (TFMGetRegistrationConfiguration::getMethodFromSysAttribute(classId,new TFMCollectorMapAttribute(subStr(classStr(TFMLookup),4,100),docTypeAttr.parmContentType())) ||
                            TFMGetRegistrationConfiguration::getMethodFromSysAttribute(classId,new TFMCollectorMapAttribute(subStr(classStr(TFMGetRegistrationConfiguration),4,100),docTypeAttr.parmContentType())) ||
                            TFMGetRegistrationConfiguration::getMethodFromSysAttribute(classId,new TFMCollectorMapAttribute(docTypeAttr.parmDocumentType(),docTypeAttr.parmContentType())))
                        {
                            tmpLookup.Description = 'PostMethod Class';
                            tmpLookup.ClassName  = DC.name() + '.' + DM.name();
                            tmpLookup.insert();
                            addedClasses.add(DC.name() + '.' + DM.name());
                        }
                    }
                    arr2 = DC.getAttributes(classStr(TFMDocumentTypeAttribute));
                    for (k = 1; k <= arr2.lastIndex(); k++)
                    {
                        docTypeAttr = arr2.value(k);

                        if (strScan(classStr(TFMPostAdhocRegistration),docTypeAttr.parmDocumentType(),1,150) && docTypeAttr.getMethodName() == DM.name())
                        {
                            tmpLookup.Description = 'PostMethod Class';
                            tmpLookup.ClassName  = DC.name() + '.' + DM.name();
                            tmpLookup.insert();
                            addedClasses.add(DC.name() + '.' + DM.name());
                        }
                    }
                }
            }


        }



    }

    sysTableLookup.parmTmpBuffer(tmpLookup);
    sysTableLookup.performFormLookup();
}

