public static void lookupAssignedWarehouses(FormControl _callingControl, UserGroupId _userGroupId)
{
    SysTableLookup      sysTableLookup  = SysTableLookup::newParameters(tablenum(MobInventLocationsGroupRights), _callingControl);
    Query query = new Query();
    QueryBuildDataSource qbds;
    qbds= query.addDataSource(tableNum(MobInventLocationsGroupRights));
    qbds.addRange(fieldNum(MobInventLocationsGroupRights,UserGroupId)).value(_userGroupId);
    sysTableLookup.parmQuery(query);

    sysTableLookup.addLookupfield(fieldNum(MobInventLocationsGroupRights,InventLocationID),true);
    sysTableLookup.performFormLookup();
}


